def solve_slide(gi, keyf):
    comps = components(gi, False)
    comps.sort(key=keyf, reverse=True)
    g = [row[:] for row in gi]
    H, W = len(g), len(g[0])
    for cells in comps:
        pos = set(cells)
        while True:
            tgt = {(r, c+1) for r, c in pos}
            if any(c+1 >= W for r, c in pos): break          # wall
            if any(t in g and g[t[0]][t[1]] != 0 and t not in pos for t in tgt): break
            pos = tgt
        for r, c in cells: g[r][c] = 0
        for r, c in pos: g[r][c] = cells and orig_color(cells, gi)
    return g

